import fs from 'fs';
import { toCsv } from './csv.js';

const [, , file, command] = process.argv;

if (!file || !command) {
  console.error('Usage: node report.js <file> <rows|summary>');
  process.exit(1);
}

const data = JSON.parse(fs.readFileSync(file, 'utf-8'));

if (command === 'rows') {
  const rows = data.map(entry => [entry.name, entry.score]);
  console.log(toCsv(rows));
} else if (command === 'summary') {
  const total = data.length;
  const best = data.reduce((max, entry) => 
    entry.score > max.score ? entry : max
  ).name;
  console.log(toCsv([[total, best]]));
} else {
  console.error('Unknown command. Use "rows" or "summary".');
  process.exit(1);
}

