import { test } from 'node:test';
import assert from 'node:assert';
import { toCsv } from './csv.js';

test('toCsv with simple fields', () => {
  const rows = [['name', 'score'], ['Alice', '100']];
  const result = toCsv(rows);
  assert.strictEqual(result, 'name,score\nAlice,100');
});

test('toCsv with comma in field', () => {
  const rows = [['name', 'score'], ['Reyes, Ana', '95']];
  const result = toCsv(rows);
  assert.strictEqual(result, 'name,score\n"Reyes, Ana",95');
});

test('toCsv with multiple commas', () => {
  const rows = [['name', 'info'], ['Smith, John, Jr.', 'data']];
  const result = toCsv(rows);
  assert.strictEqual(result, 'name,info\n"Smith, John, Jr.",data');
});

test('toCsv with quotes in field', () => {
  const rows = [['name', 'quote'], ['Bob', 'said "hello"']];
  const result = toCsv(rows);
  assert.strictEqual(result, 'name,quote\nBob,"said ""hello"""');
});

test('toCsv with newlines in field', () => {
  const rows = [['name', 'note'], ['Charlie', 'line1\nline2']];
  const result = toCsv(rows);
  assert.strictEqual(result, 'name,note\nCharlie,"line1\nline2"');
});
